class Robot:
    def __init__(self, name, battery=100):
        self.name = name  # Constructor sets up the bot
        self.battery = battery
        print(f"{self.name} powered on! 🔋: {self.battery}%")

    def dance(self, style):
        if self.battery <= 10:
            print("Error: Need coffee (or a charger).")
        else:
            self.battery -= 20
            print(f"{self.name} busts out {style} moves! 🔥 🔋: {self.battery}%")

    def recharge(self):
        self.battery = 100
        print(f"{self.name} chugs espresso. FULL POWER! ⚡")

# Let’s party!
robo = Robot("DiscoBot")  # Step 1: Instantiate
robo.dance("the worm")    # Step 2: Call method
robo.dance("flossing")    # Repeat (but battery drains!)
robo.recharge()           # Encapsulation FTW!
```

