class Robot:
    def __init__(self, name):
        self.name = name
        self.battery = 100
        self.last_dance = None
        print(f"{name} online. Prepare for sass.")

    def dance(self, style):
        self.last_dance = style
        if self.battery <= 0:
            print("Error: *collapses dramatically*")
            self.order_pizza()
        else:
            self.battery -= 25
            print(f"{self.name} attempts {style}... {self._generate_roast()} 🔋: {self.battery}%")

    def _generate_roast(self):  # Private method for maximum snark
        roasts = {
            "floss": "Did your code just glitch?",
            "moonwalk": "1980s called. They want their moves back.",
            "default": "Yikes. My servos are cringing."
        }
        return roasts.get(self.last_dance, roasts["default"])

    def order_pizza(self):
        print(f"{self.name} demands pizza. Extra snark on top. 🍕")

# Let's embarrass this bot
