import java.util.Random;

public class DanceBattle {
    private Robot[] contestants;
    private String[] styles = {"floss", "moonwalk", "robot", "disco", "cha-cha"};

    public DanceBattle(Robot bot1, Robot bot2) {
        this.contestants = new Robot[]{bot1, bot2};
        System.out.println("\n⚡ BATTLE START: " + bot1.getName() + " vs " + bot2.getName() + " ⚡");
    }

    public void startBattle(int rounds) {
        Random rand = new Random();
        for (int round = 1; round <= rounds; round++) {
            System.out.println("\n—— ROUND " + round + " ——");
            for (Robot bot : contestants) {
                bot.dance(styles[rand.nextInt(styles.length)]);
            }
            roastExchange();
        }
    }

    private void roastExchange() {
        System.out.println("\n🔥 ROAST SESSION 🔥");
        System.out.println(contestants[0].getName() + ": " + contestants[0].generateRoast(contestants[1].getLastDance()));
        System.out.println(contestants[1].getName() + ": " + contestants[1].generateRoast(contestants[0].getLastDance()));
    }

    public static void main(String[] args) {
        Robot robo1 = new Robot("SassBot-9000");
        Robot robo2 = new Robot("RoastMaster-3000");
        DanceBattle battle = new DanceBattle(robo1, robo2);
        battle.startBattle(3);
    }
}
```

